system_kql:
// CAVEAT: No concrete threshold number was given for 'frequent', so no threshold filter was added.
// CAVEAT: No concrete filter was added for user_agent because no specific values were provided.
imNetworkSession
| where NetworkApplicationProtocol contains "ldap"
| where Dst contains "ldap://"
| summarize ConnectionCount = count(), DistinctLdapUrls = make_set(Dst), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SrcIpAddr, Dst, bin(TimeGenerated, 1d)

// CAVEAT: No concrete time window or threshold was given for 'recent' authentication events, so no time filter was added on AuthenticationTimestamp.
imProcessCreate
| where ActingProcessName == "powershell"
| join kind=inner (
    imAuthentication
) on ActorUsername

// CAVEAT: No concrete time window or threshold was specified for 'recent' authentication events, so no time filter was added.
imProcessCreate
| where ActingProcessName == "powershell.exe"
| join kind=inner (
    imAuthentication
) on ActorUserId
